{
  "portfolio_size": 15,
  "conflicts": [
    {
      "company": "DispatchPro",
      "type": "direct",
      "severity": "blocking",
      "rationale": "DispatchPro operates in Field Service Management \u2014 the same product category and customer segment as Cadence (SMB field-service scheduling and dispatch). Investing in Cadence would create a direct head-to-head conflict within the same fund portfolio."
    },
    {
      "company": "ServiceTitan",
      "type": "direct",
      "severity": "manageable",
      "rationale": "ServiceTitan is a Field Service Management platform. While ServiceTitan has moved upmarket toward larger contractors, both products compete for the field service software budget of service businesses, creating a direct category conflict. Severity is manageable given ServiceTitan's enterprise focus versus Cadence's SMB positioning."
    },
    {
      "company": "HouseCall Pro",
      "type": "direct",
      "severity": "blocking",
      "rationale": "HouseCall Pro is an SMB home services SaaS platform offering scheduling, dispatch, and customer management \u2014 nearly identical to Cadence's product and customer profile (SMB field service businesses). This is a direct, blocking conflict with significant overlap in product, customer segment, and go-to-market."
    },
    {
      "company": "Jobber",
      "type": "direct",
      "severity": "blocking",
      "rationale": "Jobber is a Field Service Management platform explicitly targeting SMB service businesses with job scheduling, crew management, and customer tracking \u2014 the same product and customer segment as Cadence. This represents a direct, blocking conflict within the fund's portfolio."
    },
    {
      "company": "FieldEdge",
      "type": "adjacent",
      "severity": "manageable",
      "rationale": "FieldEdge targets HVAC and plumbing SMBs with vertical field service software. Cadence targets SMB field service businesses broadly, which includes HVAC and plumbing contractors. The customer base overlaps significantly, though FieldEdge's vertical specificity creates some differentiation."
    },
    {
      "company": "Kickserv",
      "type": "direct",
      "severity": "blocking",
      "rationale": "Kickserv is a Field Service SaaS product for SMBs offering scheduling, dispatch, and job management \u2014 identical category and customer profile to Cadence. Investing in both would constitute a direct portfolio conflict."
    },
    {
      "company": "WorkWave",
      "type": "direct",
      "severity": "manageable",
      "rationale": "WorkWave provides field operations software for service businesses. The product category overlaps directly with Cadence's field-service scheduling and dispatch platform. Severity is manageable given WorkWave's broader/enterprise-leaning market positioning relative to Cadence's SMB focus."
    },
    {
      "company": "ReachOut",
      "type": "direct",
      "severity": "manageable",
      "rationale": "ReachOut is a field service automation platform operating in the same product category as Cadence. The direct overlap in field service scheduling and dispatch creates a conflict, though scale and geographic differences may make this manageable."
    },
    {
      "company": "Connecteam",
      "type": "adjacent",
      "severity": "manageable",
      "rationale": "Connecteam focuses on deskless worker management including scheduling and communication for field teams \u2014 a feature set adjacent to Cadence's crew and job management capabilities. The SMB field service customer base is shared, creating an adjacent conflict with manageable severity."
    },
    {
      "company": "Ramp",
      "type": "customer_overlap",
      "severity": "manageable",
      "rationale": "Ramp serves SMB and mid-market businesses with finance operations tooling. Cadence's SMB field service customers are a subset of Ramp's customer base, creating customer overlap. Products are non-competing, making this a manageable, low-concern overlap."
    },
